struct User: Encodable {
    let id: UUID, email: String, internalNotes: String
    let requested: Set<String>
    enum CodingKeys: String, CodingKey { case id, email, internalNotes }

    func encode(to encoder: Encoder) throws {
        var c = encoder.container(keyedBy: CodingKeys.self)
        if requested.contains("id")    { try c.encode(id, forKey: .id) }
        if requested.contains("email") { try c.encode(email, forKey: .email) }
    }
}

